endpoints.truth_yaml:
put:
  operationId: updateProject
  x-verification-status: LIVE-VERIFIED
  x-evidence:
    - PROBE-LOG/20260521-050000-put.workspaces.projects-happy-path.json
  x-notes: |
    Full-replacement PUT. Required body field: name. Optional: archived, billable,
    isPublic, clientId, color, note, costRate, hourlyRate, estimate, budgetEstimate,
    estimateReset, timeEstimate, memberships, tasks. Tool does GET-then-PUT merge
    to preserve unspecified fields. Archival is handled via archived:true in this
    same body -- no /archive sub-path exists.
  x-truth-iter: iter21
  parameters:
    - {name: workspaceId, in: path, required: true, schema: {type: string}}
    - {name: projectId, in: path, required: true, schema: {type: string}}
  requestBody:
    required: true
    content:
      application/json:
        schema:
          type: object
          required: [name]
          properties:
            name: {type: string, maxLength: 150}
            archived: {type: boolean}
            billable: {type: boolean}
            isPublic: {type: boolean}
            clientId: {type: string}
            color: {type: string, pattern: '^#[0-9a-fA-F]{6}$'}
            note: {type: string}
            costRate: {type: object, description: Rate object with amount and currency}
            hourlyRate: {type: object, description: Rate object with amount and currency}
            estimate: {type: object, description: Estimate object}
            budgetEstimate: {type: object}
            estimateReset: {type: object}
            timeEstimate: {type: object}
            memberships: {type: array, items: {type: object}}
            tasks: {type: array, items: {type: object}}
  responses:
    '200':
      description: Updated project object
      content:
        application/json:
          schema:
            type: object
            properties:
              id: {type: string}
              name: {type: string}
              archived: {type: boolean}
              billable: {type: boolean}
              workspaceId: {type: string}

put:
  operationId: updateTask
  x-verification-status: LIVE-VERIFIED
  x-evidence:
    - PROBE-LOG/20260521-050000-put.workspaces.projects.tasks-happy-path.json
  x-notes: |
    Full-replacement PUT for a task. Required body field: name. Optional:
    billable, status (ACTIVE|DONE), estimate, assigneeId, assigneeIds,
    userGroupIds, budgetEstimate. Tool does GET-then-layered-merge to avoid
    wiping unspecified fields. Supported query params: contains-assignee,
    membership-status.
  x-truth-iter: iter21
  parameters:
    - {name: workspaceId, in: path, required: true, schema: {type: string}}
    - {name: projectId, in: path, required: true, schema: {type: string}}
    - {name: taskId, in: path, required: true, schema: {type: string}}
    - {name: contains-assignee, in: query, required: false, schema: {type: boolean}}
    - {name: membership-status, in: query, required: false, schema: {type: string, enum: [PENDING, ACTIVE, DECLINED, INACTIVE, ALL]}}
  requestBody:
    required: true
    content:
      application/json:
        schema:
          type: object
          required: [name]
          properties:
            name: {type: string, maxLength: 150}
            billable: {type: boolean}
            status: {type: string, enum: [ACTIVE, DONE]}
            estimate: {type: string, description: ISO 8601 duration e.g. PT8H}
            assigneeId: {type: string}
            assigneeIds: {type: array, items: {type: string}}
            userGroupIds: {type: array, items: {type: string}}
            budgetEstimate: {type: integer, description: Budget estimate in minor currency units}
  responses:
    '200':
      description: Updated task object
      content:
        application/json:
          schema:
            type: object
            properties:
              id: {type: string}
              name: {type: string}
              projectId: {type: string}
              billable: {type: boolean}
              status: {type: string}
              estimate: {type: string}
              hourlyRate: {type: object}
